use chrono::{DateTime, Utc};
use diesel::prelude::*;
use diesel_async::{AsyncPgConnection, RunQueryDsl};
use serde::{Serialize, Serializer};
use uuid::Uuid;

use crate::schema::term_payments;

// Generated by `diesel print-schema` from the `payment_method` Postgres enum,
// so it always matches the database.
pub use crate::schema::rust_types::PaymentMethod;

pub(crate) mod sql {
	use diesel::expression::functions::declare_sql_function;
	use diesel::sql_types::{Bool, Text, Varchar};

	// Defined in migrations/0002_dues_logic. Arguments are passed by name, so
	// these parameter names must match the SQL function's.
	#[declare_sql_function(named_parameters = true)]
	extern "SQL" {
		/// False if the term doesn't exist.
		fn has_paid_term(member_net_id: Varchar, semester_name: Text) -> Bool;

		/// False if no term has started yet.
		fn has_paid_current_term(member_net_id: Varchar) -> Bool;
	}
}

// TO DO: this isn't a very elegant way to handle Enum -> &str -> Serialize,
// but using `#[derive(Serialize)]` would require disabling diesel's
// generation of enums, which may improve over time (two weeks ago,
// diesel 2.4.0 created `#[derive(Enum)]` finally!) so we should put a rain
// check on this.
impl PaymentMethod {
	/// The same spelling as the `payment_method` Postgres enum.
	pub fn as_str(self) -> &'static str {
		match self {
			PaymentMethod::Cash => "cash",
			PaymentMethod::Stripe => "stripe",
			PaymentMethod::Square => "square",
			PaymentMethod::Paypal => "paypal",
			PaymentMethod::Venmo => "venmo",
			PaymentMethod::Cashapp => "cashapp",
			PaymentMethod::Other => "other",
		}
	}
}

// schema.rs is generated, so the derive can't go there.
impl Serialize for PaymentMethod {
	fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
		s.serialize_str(self.as_str())
	}
}

#[derive(Queryable, Selectable, Identifiable, Serialize, Debug)]
#[diesel(table_name = crate::schema::term_payments)]
#[diesel(check_for_backend(diesel::pg::Pg))]
pub struct TermPayment {
	pub id: Uuid,
	pub net_id: String,
	pub time_purchased: DateTime<Utc>,
	pub amount_paid_cents: i32,
	pub method: PaymentMethod,
	/// Raw responses from the payment processor; not sent to clients.
	#[serde(skip)]
	pub metadata: serde_json::Value,
}

/// Every payment `net_id` has made, newest first.
pub async fn payments_for(
	conn: &mut AsyncPgConnection,
	net_id: &str,
) -> QueryResult<Vec<TermPayment>> {
	term_payments::table
		.filter(term_payments::net_id.eq(net_id))
		.order(term_payments::time_purchased.desc())
		.select(TermPayment::as_select())
		.load(conn)
		.await
}
